```go
for i := range entries {
    e := &entries[i]
    lane := lanes[e.Kind]
    res := ReconResult{Index: e.Index, Kind: e.Kind, ID: e.ID}
    k := balanceKey{e.Account, e.Asset}
    rec := lane.byID[e.ID]  // nil if absent

