package payflow

// 临时差分验证：重构前后对同一批确定性伪随机场景生成完全一致的报告。
// 通过 RECON_DUMP 环境变量指定输出文件；验证完成后删除本文件。

import (
	"encoding/json"
	"fmt"
	"math/rand"
	"os"
	"path/filepath"
	"testing"
)

func TestReconDump(t *testing.T) {
	out := os.Getenv("RECON_DUMP")
	if out == "" {
		t.Skip("RECON_DUMP not set")
	}
	f, err := os.Create(out)
	if err != nil {
		t.Fatal(err)
	}
	defer f.Close()
	enc := json.NewEncoder(f)

	rng := rand.New(rand.NewSource(20261003))
	accounts := []string{"alice", "bob", "carol"}
	assets := []string{"usdc", "eth"}

	for scenario := 0; scenario < 60; scenario++ {
		dir := t.TempDir()
		path := filepath.Join(dir, "ledger.json")
		var init []BalanceInit
		for _, a := range accounts {
			for _, as := range assets {
				init = append(init, BalanceInit{Account: a, Asset: as, Balance: 1 << 40})
			}
		}
		if err := CreateLedger(path, init); err != nil {
			t.Fatal(err)
		}
		l, err := Open(path)
		if err != nil {
			t.Fatal(err)
		}
		// 随机提交若干付款与退款。
		nPay := rng.Intn(8)
		for i := 0; i < nPay; i++ {
			amt := int64(rng.Intn(100000) + 1)
			l.Submit(FeeBatch{FeeBps: rng.Intn(500), Intents: []PaymentIntent{{
				ID: fmt.Sprintf("p%d", i), Account: accounts[rng.Intn(3)],
				Asset: assets[rng.Intn(2)], Amount: &amt, State: "pending",
			}}})
		}
		snap, _ := l.Query()
		for _, r := range snap.Settlements {
			if rng.Intn(2) == 0 {
				l.Refund(RefundBatch{Refunds: []RefundRequest{{
					ID: "r-" + r.ID, SettlementID: r.ID, Reason: "x",
				}}})
			}
		}
		snap, _ = l.Query()

		// 随机生成流水：部分命中、部分缺失、部分重复、部分字段不符。
		var entries []FlowEntry
		addEntry := func(kind, id string, mutate bool) {
			e := FlowEntry{Index: len(entries), Kind: kind, ID: id,
				Account: accounts[rng.Intn(3)], Asset: assets[rng.Intn(2)],
				Amount: 1, Fee: 0, Charged: 1}
			if kind == "refund" {
				e.SettlementID = "p0"
			}
			entries = append(entries, e)
			_ = mutate
		}
		for _, r := range snap.Settlements {
			switch rng.Intn(4) {
			case 0: // 精确命中
				entries = append(entries, FlowEntry{Index: len(entries), Kind: "payment",
					ID: r.ID, Account: r.Account, Asset: r.Asset,
					Amount: r.Amount, Fee: r.Fee, Charged: r.Charged})
			case 1: // 字段不符
				entries = append(entries, FlowEntry{Index: len(entries), Kind: "payment",
					ID: r.ID, Account: r.Account, Asset: r.Asset,
					Amount: r.Amount + 1, Fee: r.Fee, Charged: r.Charged})
			case 2: // 重复组
				for j := 0; j < 2; j++ {
					entries = append(entries, FlowEntry{Index: len(entries), Kind: "payment",
						ID: r.ID, Account: r.Account, Asset: r.Asset,
						Amount: r.Amount, Fee: r.Fee, Charged: r.Charged})
				}
			}
		}
		for _, r := range snap.Refunds {
			switch rng.Intn(3) {
			case 0:
				entries = append(entries, FlowEntry{Index: len(entries), Kind: "refund",
					ID: r.ID, Account: r.Account, Asset: r.Asset, Amount: r.Amount,
					Fee: r.Fee, Charged: r.Charged, SettlementID: r.SettlementID})
			case 1:
				entries = append(entries, FlowEntry{Index: len(entries), Kind: "refund",
					ID: r.ID, Account: r.Account, Asset: r.Asset, Amount: r.Amount,
					Fee: r.Fee, Charged: r.Charged, SettlementID: "wrong"})
			}
		}
		addEntry("payment", "ghost", false)
		addEntry("refund", "ghost-r", false)

		// 随机范围（含空范围与截断范围）。
		i64 := func(v int64) *int64 { return &v }
		for trial := 0; trial < 4; trial++ {
			bounds := ReconcileBounds{}
			maxP := int64(len(snap.Settlements))
			maxR := int64(len(snap.Refunds))
			switch trial {
			case 1:
				bounds.PaymentThrough = i64(maxP / 2)
				bounds.RefundThrough = i64(maxR / 2)
			case 2:
				bounds.PaymentAfter = i64(maxP / 2)
				bounds.RefundAfter = i64(maxR / 2)
			case 3:
				bounds.PaymentAfter = i64(1)
				bounds.PaymentThrough = i64(1)
				bounds.RefundAfter = i64(0)
				bounds.RefundThrough = i64(0)
			}
			rep, err := l.ReconcileFlowRanged(entries, bounds)
			if err != nil {
				t.Fatal(err)
			}
			if err := enc.Encode(rep); err != nil {
				t.Fatal(err)
			}
		}
		l.Close()
	}
}

